const char *const *logo_builtin_find(const char *id, int *rows) {
  if (!id)
    return NULL;
  for (size_t i = 0; i < sizeof(builtin_logos) / sizeof(builtin_logos[0]);
       i++)
    if (strcasecmp(builtin_logos[i].id, id) == 0) {
      if (rows)
        *rows = builtin_logos[i].rows;
      return builtin_logos[i].art;
    }
  return NULL;
}

const char *logo_distro_color(const char *id) {
  if (!id)
    return NULL;
  for (size_t i = 0; i < sizeof(builtin_logos) / sizeof(builtin_logos[0]);
       i++)
    if (strcasecmp(builtin_logos[i].id, id) == 0)
      return builtin_logos[i].color;
  return NULL;
}
